import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"4、【蒙】 坎下艮上","description":"横渠易说 - 4、【蒙】 坎下艮上","frontmatter":{"title":"4、【蒙】 坎下艮上","description":"横渠易说 - 4、【蒙】 坎下艮上"},"headers":[],"relativePath":"zh/classics/hengqu/006.md","filePath":"zh/classics/hengqu/006.md"}'),t={name:"zh/classics/hengqu/006.md"};function l(n,a,s,c,d,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_4、【蒙】-坎下艮上" tabindex="-1">4、【蒙】 坎下艮上 <a class="header-anchor" href="#_4、【蒙】-坎下艮上" aria-label="Permalink to “4、【蒙】 坎下艮上”">​</a></h1><p>礼闻取道义于人，不闻取其人之身。来之为言，属有道义者谓之来。来学者，就道义而学之，往教者，致其人而取教也；“童蒙求我，匪我求童蒙”是也。 教人当以次，守得定，不妄施。易曰：“初筮告，再三渎，渎则不告”，是刚中之德也。</p><p>彖曰：蒙，山下有险，险而止，蒙。“险而止蒙”，蒙亨以亨行时中也。“匪我求童蒙，童蒙求我”，志应也。“初筮告”，以刚中也。“再三渎，渎则不告”，渎蒙也。蒙以养正，圣功也。</p><p>夫险而不止则入于坎，入于蹇，不止则是安其危之类也。以其知险而止也，故成蒙之义方以有求。“童蒙求我，匪我求童蒙”，以蒙而求，故能时中，所以亨也。 ［险而止蒙，夫于不当止而止，是险也，如告子之不动心，必以义为外，是险而止也。蒙险在内，是蒙昧之义。蒙方始务求学，而得之始，是得所止也。若蹇则是险在外者也。人心多则无由光明，“蒙杂而着”，“着”，古“着”字，杂着于物，所以为蒙。蒙，昏蒙也。“蒙亨”，以亨行时中也。</p><h3 id="象曰-山下出泉-蒙-君子以果行育德。" tabindex="-1">象曰：山下出泉，蒙，君子以果行育德。 <a class="header-anchor" href="#象曰-山下出泉-蒙-君子以果行育德。" aria-label="Permalink to “象曰：山下出泉，蒙，君子以果行育德。”">​</a></h3><p>时［中］之义甚大，如“蒙亨以亨行时中也”者，蒙何(尝)［以］有亨？以九二之亨行蒙者之时中，故蒙所以得亨也；蒙无遽亨之理，以九二循循行时中之亨也。蒙卦之义，主之者全在九二，彖之所论，皆二之义。教者但观蒙者时之所及则道之，此是以亨行时［中］也；此时也，正所谓如时雨化之。如既引之中道而不使之通，则是教者之过；当时而道之使不失其正，则是教者之功。［“蒙以养正，圣功也”，］养其蒙使正者，圣人之功也。</p><h3 id="初六-发蒙-利用刑人-用说桎梏-以往吝。-象曰-利用刑人-以正法也。" tabindex="-1">初六，发蒙，利用刑人，用说桎梏，以往吝。 象曰：“利用刑人”，以正法也。 <a class="header-anchor" href="#初六-发蒙-利用刑人-用说桎梏-以往吝。-象曰-利用刑人-以正法也。" aria-label="Permalink to “初六，发蒙，利用刑人，用说桎梏，以往吝。 象曰：“利用刑人”，以正法也。”">​</a></h3><p>以柔下贤，居于坎陷，然无所私系，用心存公，虽不能谕人于道以辨曲直，正法可也。善行法者多说于任刑，道非弘矣，故以往吝，故一作终。故君子哀矜而勿喜也。</p><h3 id="九二-包蒙吉。纳妇吉-子克家。-象曰-子克家-刚柔接也。" tabindex="-1">九二，包蒙吉。纳妇吉，子克家。 象曰：“子克家”，刚柔接也。 <a class="header-anchor" href="#九二-包蒙吉。纳妇吉-子克家。-象曰-子克家-刚柔接也。" aria-label="Permalink to “九二，包蒙吉。纳妇吉，子克家。 象曰：“子克家”，刚柔接也。”">​</a></h3><p>择妇而纳之则吉。 九二以下卦之中主卦德，故曰子克家”。以子任家，必刚柔得中乃济，不可严厉也。</p><h3 id="六三-勿用取女-见金夫-不有躬-无攸利。-象曰-勿用取女-行不顺也。" tabindex="-1">六三，勿用取女，见金夫，不有躬，无攸利。 象曰：“勿用取女”，行不顺也。 <a class="header-anchor" href="#六三-勿用取女-见金夫-不有躬-无攸利。-象曰-勿用取女-行不顺也。" aria-label="Permalink to “六三，勿用取女，见金夫，不有躬，无攸利。 象曰：“勿用取女”，行不顺也。”">​</a></h3><p>金夫，二也；“不有躬”，履非正则不能固于一也。</p><h3 id="六四-困蒙吝。-象曰-困蒙之吝-独远实也。" tabindex="-1">六四，困蒙吝。 象曰：困蒙之吝，独远实也。 <a class="header-anchor" href="#六四-困蒙吝。-象曰-困蒙之吝-独远实也。" aria-label="Permalink to “六四，困蒙吝。 象曰：困蒙之吝，独远实也。”">​</a></h3><h3 id="六五-童蒙吉。-象曰-童蒙之吉-顺以巽也。" tabindex="-1">六五，童蒙吉。 象曰：童蒙之吉，顺以巽也。 <a class="header-anchor" href="#六五-童蒙吉。-象曰-童蒙之吉-顺以巽也。" aria-label="Permalink to “六五，童蒙吉。 象曰：童蒙之吉，顺以巽也。”">​</a></h3><p>不愿不信，蒙之失正者也。故蒙正如童吉，与夫彖之义同。</p><h3 id="上九-击蒙-不利为寇-利御寇。-象曰-利用御寇-上下顺也。" tabindex="-1">上九，击蒙，不利为寇，利御寇。 象曰：利用御寇，上下顺也。 <a class="header-anchor" href="#上九-击蒙-不利为寇-利御寇。-象曰-利用御寇-上下顺也。" aria-label="Permalink to “上九，击蒙，不利为寇，利御寇。 象曰：利用御寇，上下顺也。”">​</a></h3><p>蒙暗犯寇，御之可也，以刚明极显而寇蒙暗，则伤义而众不率也。九二以刚居中，故能包蒙而吉。</p>',17)])])}const m=e(t,[["render",l]]);export{_ as __pageData,m as default};
